// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/v1/analytics/overview", wrapper.GetAnalyticsOverview)
	m.HandleFunc("POST "+options.BaseURL+"/v1/attachment-uploads", wrapper.CreateAttachmentUpload)
	m.HandleFunc("GET "+options.BaseURL+"/v1/attachments/{id}/download", wrapper.DownloadAttachment)
	m.HandleFunc("GET "+options.BaseURL+"/v1/auth/config", wrapper.GetAuthConfig)
	m.HandleFunc("POST "+options.BaseURL+"/v1/auth/google", wrapper.GoogleLogin)
	m.HandleFunc("POST "+options.BaseURL+"/v1/auth/login", wrapper.Login)
	m.HandleFunc("POST "+options.BaseURL+"/v1/auth/logout", wrapper.Logout)
	m.HandleFunc("GET "+options.BaseURL+"/v1/feedback", wrapper.ListFeedback)
	m.HandleFunc("POST "+options.BaseURL+"/v1/feedback", wrapper.CreateFeedback)
	m.HandleFunc("GET "+options.BaseURL+"/v1/feedback/{id}", wrapper.GetFeedback)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/feedback/{id}", wrapper.UpdateFeedback)
	m.HandleFunc("GET "+options.BaseURL+"/v1/feedback/{id}/activities", wrapper.ListFeedbackActivities)
	m.HandleFunc("POST "+options.BaseURL+"/v1/feedback/{id}/notes", wrapper.AddFeedbackNote)
	m.HandleFunc("POST "+options.BaseURL+"/v1/internal-feedback", wrapper.CreateInternalFeedback)
	m.HandleFunc("GET "+options.BaseURL+"/v1/me", wrapper.GetMe)
	m.HandleFunc("GET "+options.BaseURL+"/v1/members", wrapper.ListMembers)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/organization", wrapper.UpdateOrganization)
	m.HandleFunc("GET "+options.BaseURL+"/v1/projects", wrapper.ListProjects)
	m.HandleFunc("POST "+options.BaseURL+"/v1/projects", wrapper.CreateProject)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/projects/{id}", wrapper.UpdateProject)
	m.HandleFunc("POST "+options.BaseURL+"/v1/projects/{id}/write-key/rotate", wrapper.RotateProjectWriteKey)
	m.HandleFunc("GET "+options.BaseURL+"/v1/sdk/config", wrapper.GetSdkConfig)
	m.HandleFunc("GET "+options.BaseURL+"/v1/setup", wrapper.GetSetupState)
	m.HandleFunc("POST "+options.BaseURL+"/v1/webhook-deliveries/{id}/replay", wrapper.ReplayWebhookDelivery)
	m.HandleFunc("GET "+options.BaseURL+"/v1/webhook-endpoints", wrapper.ListWebhookEndpoints)
	m.HandleFunc("POST "+options.BaseURL+"/v1/webhook-endpoints", wrapper.CreateWebhookEndpoint)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/webhook-endpoints/{id}", wrapper.DeleteWebhookEndpoint)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/webhook-endpoints/{id}", wrapper.UpdateWebhookEndpoint)
	m.HandleFunc("GET "+options.BaseURL+"/v1/webhook-endpoints/{id}/deliveries", wrapper.ListWebhookDeliveries)

	return m
}
